import sys

def solve(n, k):
    if k > n - 1:
        return "-1"

    # Create a list of numbers from 1 to n
    A = list(range(1, n + 1))

    # Place k elements at their correct positions
    for i in range(k):
        A[i] = i + 1

    # Swap the remaining elements to ensure no other fixed points
    for i in range(k, n - 1):
        A[i], A[i + 1] = A[i + 1], A[i]

    return " ".join(map(str, A))

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2
        results.append(solve(n, k))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
